#!/usr/bin/env Rscript
source("code/01_common.R")
runs<-list(A_baseline_origident_theta2_lambda1=list(group="orig.ident",theta=2,lambda=1),B_origident_theta4_lambda1=list(group="orig.ident",theta=4,lambda=1),C_origident_theta6_lambda0.5=list(group="orig.ident",theta=6,lambda=.5),D_dataset_theta4_lambda1=list(group="dataset",theta=4,lambda=1))
run<-Sys.getenv("TNK_RUN",unset="");if(!run%in%names(runs))stop("Invalid TNK_RUN");s<-runs[[run]];out<-file.path(r2,"TNK",run);dir.create(out,recursive=TRUE,showWarnings=FALSE);t0<-Sys.time();o<-qs::qread(file.path(r2,"TNK","TNK_round2_common_preprocessed.qs"));stopifnot(ncol(o)==124746,ncol(Embeddings(o[["pca_round2_common"]]))==50)
o<-harmony::RunHarmony(o,group.by.vars=s$group,reduction.use="pca_round2_common",dims.use=1:30,reduction.save="harmony_round2",theta=s$theta,lambda=s$lambda,max_iter=20,verbose=TRUE);o<-FindNeighbors(o,reduction="harmony_round2",dims=1:30,graph.name=c("round2_nn","round2_snn"),verbose=TRUE);o<-FindClusters(o,graph.name="round2_snn",resolution=.8,cluster.name="cluster_v2_round2",algorithm=1,random.seed=20260915,verbose=TRUE);o$cluster_v2_round2<-factor(as.character(o$cluster_v2_round2),levels=cluster_levels(o$cluster_v2_round2));Idents(o)<-"cluster_v2_round2";o<-RunUMAP(o,reduction="harmony_round2",dims=1:30,reduction.name="umap_round2",reduction.key="round2UMAP_",seed.use=20260915,verbose=TRUE)
save_pair(umap_plot(o,"cluster_v2_round2",label=TRUE),file.path(out,paste0("01_umap_cluster_",run)));save_pair(umap_plot(o,"dataset"),file.path(out,paste0("02_umap_dataset_",run)));save_pair(umap_plot(o,"orig.ident"),file.path(out,paste0("03_umap_specimen_",run)),13,9);save_pair(umap_plot(o,"orig.ident",legend=FALSE),file.path(out,paste0("03_umap_specimen_",run,"_nolegend")),10,8.5);save_pair(umap_plot(o,"cluster_v2_round1",label=TRUE),file.path(out,paste0("04_umap_round1_cluster_",run)))
panel<-read.csv(file.path(r1,"TNK","marker_panel_used.csv"),check.names=FALSE,stringsAsFactors=FALSE);write.csv(panel,file.path(out,"marker_panel_used_round2.csv"),row.names=FALSE);write.csv(panel[!panel$present,,drop=FALSE],file.path(out,"missing_markers_round2.csv"),row.names=FALSE);dotplot_grouped(o,panel[panel$present,,drop=FALSE],"cluster_v2_round2",file.path(out,paste0("05_dotplot_frozen_markers_",run)))
suf<-paste0("_",run);nmarkers<-write_markers(o,out,"cluster_v2_round2",suf);audit<-write_composition(o,out,"cluster_v2_round2",suf);map<-write_mapping(o,out,"cluster_v2_round2",suf);decision_template(o,out,"cluster_v2_round2",map)
# Quantitative sensitivity audit on a deterministic 30k-cell sample in Harmony space.
set.seed(20260915);ix<-sort(sample(seq_len(ncol(o)),min(30000,ncol(o))));emb<-Embeddings(o[["harmony_round2"]]);nn<-RANN::nn2(emb,query=emb[ix,,drop=FALSE],k=31)$nn.idx[,-1,drop=FALSE];ds<-as.character(o$dataset);sp<-as.character(o$orig.ident);r1cl<-as.character(o$cluster_v2_round1);family<-rep("Other",length(r1cl));family[r1cl%in%c("1","3","4","16")]<-"CD8_GZMK_core";family[r1cl%in%c("2","18")]<-"CD8_GZMK_island_review";family[r1cl%in%c("0","9")]<-"Exhausted_review";family[r1cl%in%c("7","8","10","13","14")]<-"CD4_Helper_review";family[r1cl%in%c("5","6","15")]<-"Treg_review";family[r1cl%in%c("11","12")]<-"NK_review";mixfun<-function(lbl)mean(vapply(seq_along(ix),function(i)mean(lbl[nn[i,]]!=lbl[ix[i]]),numeric(1)));pres<-mean(vapply(seq_along(ix),function(i)mean(family[nn[i,]]==family[ix[i]]),numeric(1)));nmi<-function(a,b){tb<-table(a,b);p<-tb/sum(tb);pa<-rowSums(p);pb<-colSums(p);mi<-sum(p[p>0]*log(p[p>0]/as.vector(outer(pa,pb))[p>0]));mi/sqrt((-sum(pa*log(pa)))*(-sum(pb*log(pb))))};comp<-data.frame(run=run,harmony_group=s$group,theta=s$theta,lambda=s$lambda,max_iter_harmony=20,resolution=.8,cells=ncol(o),n_clusters=length(unique(o$cluster_v2_round2)),dataset_neighbor_mixing=mixfun(ds),specimen_neighbor_mixing=mixfun(sp),round1_family_neighbor_preservation=pres,round1_cluster_to_round2_NMI=nmi(r1cl,as.character(o$cluster_v2_round2)),n_specimen_gt50=sum(audit$warning_single_specimen_gt50),n_dataset_gt70=sum(audit$warning_single_dataset_gt70),n_dataset_gt90=sum(audit$warning_dataset_specific_island),stringsAsFactors=FALSE);write.csv(comp,file.path(out,paste0("sensitivity_metrics_",run,".csv")),row.names=FALSE)
o$round2_tnk_run<-run;o$round2_harmony_group<-s$group;o$round2_harmony_theta<-s$theta;o$round2_harmony_lambda<-s$lambda;o$round2_harmony_max_iter<-20;o$round2_resolution<-.8;o$round2_annotation_status<-"UNANNOTATED_MANUAL_SELECTION_REQUIRED";qs::qsave(o,file.path(out,paste0("TNK_round2_",run,".qs")),preset="high",nthreads=16);write.csv(transform(comp,runtime_minutes=as.numeric(difftime(Sys.time(),t0,units="mins")),n_markers=nmarkers),file.path(out,paste0("run_summary_",run,".csv")),row.names=FALSE);message("TNK_RUN_DONE ",run)
